"use client";

import { useRef, useState, type MouseEvent } from "react";

import { Button } from "@/components/ui/button";

import {
  KOREA_MAP_INSET,
  KOREA_MAP_PATHS,
  KOREA_MAP_VIEWBOX,
  type KoreaMapInset,
} from "./korea-map-paths";
import { RegionCartogram } from "./cartogram";
import {
  RegionHoverTip,
  buildRegionStats,
  regionFillColor,
  type RegionDatum,
  type RegionStats,
} from "./shared";

// 3D 돌출 — 바닥(0,0)→윗면(EXTRUDE_X,Y) 사이를 레이어로 채워 한몸 프리즘으로 보이게.
const EXTRUDE_X = -4;
const EXTRUDE_Y = -8;
const EXTRUDE_STEPS = 8;

// 범례 숫자 축약 (131만·2.6만) — 값 규모가 달라도 같은 포맷으로 통일.
const COMPACT = new Intl.NumberFormat("ko", { notation: "compact" });

/**
 * hover 강조에 쓰는 파생 색 2종 — 테마 프리셋에 새 토큰을 요구하지 않도록
 * primary·background·foreground 조합으로 루트에서 정의한다(모든 프리셋 자동 대응).
 * --map-low: 색 스케일 하한(옅은 틴트) / --map-side: 3D 돌출 측면(어두운 면).
 */
const DERIVED_TOKEN_CLASS = [
  "[--map-low:color-mix(in_oklch,var(--primary)_15%,var(--background))]",
  "[--map-side:color-mix(in_oklch,var(--primary)_55%,var(--foreground))]",
  "dark:[--map-side:color-mix(in_oklch,var(--primary)_60%,var(--background))]",
].join(" ");

export type RegionMapView = "geo" | "carto";

export interface RegionMapProps {
  /** 시/도별 값 — region 은 공식 명칭("서울특별시" 등)과 일치해야 한다. */
  data: RegionDatum[];
  /** 툴팁·aria 에 쓰는 값 이름 (예: "사업자", "가맹점"). */
  valueLabel?: string;
  /** 값 단위 접미사 (예: "건", "곳"). */
  unit?: string;
  /** 클릭 필터 연동 — 미지정 시 표시 전용으로 동작한다. */
  selectedRegion?: string;
  onRegionClick?: (region: string) => void;
  defaultView?: RegionMapView;
}

/**
 * 한국 시/도 분포 지도 (bizinfo #233 이식, #56).
 *
 * 지리 지도(디폴트) ↔ 타일 카토그램 토글. hover 시 지역이 3D 프리즘으로
 * 돌출하고 리치 툴팁(값·비중·순위·상위 5 랭킹 바)이 따라붙는다.
 * 카토그램은 타일 면적이 값에 비례해 지리 면적 왜곡을 보완한다.
 */
export function RegionMap({
  data,
  valueLabel = "값",
  unit = "",
  selectedRegion = "",
  onRegionClick,
  defaultView = "geo",
}: RegionMapProps) {
  const [view, setView] = useState<RegionMapView>(defaultView);

  if (data.length === 0) {
    return (
      <div className="text-muted-foreground flex h-64 items-center justify-center text-sm">
        표시할 지역 데이터가 없습니다.
      </div>
    );
  }

  return (
    <div className={`flex flex-col gap-3 ${DERIVED_TOKEN_CLASS}`}>
      <div className="flex justify-end gap-1">
        {(
          [
            { key: "geo", label: "지리 지도" },
            { key: "carto", label: "카토그램" },
          ] as const
        ).map((v) => (
          <Button
            key={v.key}
            type="button"
            size="xs"
            variant={view === v.key ? "default" : "outline"}
            onClick={() => setView(v.key)}
          >
            {v.label}
          </Button>
        ))}
      </div>

      {view === "geo" ? (
        <GeoMapView
          data={data}
          valueLabel={valueLabel}
          unit={unit}
          selectedRegion={selectedRegion}
          onRegionClick={onRegionClick}
        />
      ) : (
        <RegionCartogram
          data={data}
          valueLabel={valueLabel}
          unit={unit}
          selectedRegion={selectedRegion}
          onRegionClick={onRegionClick}
        />
      )}
    </div>
  );
}

interface GeoMapViewProps {
  data: RegionDatum[];
  valueLabel: string;
  unit: string;
  selectedRegion: string;
  onRegionClick?: (region: string) => void;
}

function GeoMapView({ data, valueLabel, unit, selectedRegion, onRegionClick }: GeoMapViewProps) {
  const boxRef = useRef<HTMLDivElement | null>(null);
  const [hovered, setHovered] = useState<string | null>(null);
  const [tipPos, setTipPos] = useState({ x: 0, y: 0, w: 0, h: 0 });

  const stats = buildRegionStats(data);
  const countByRegion = new Map(data.map((r) => [r.region, r.count]));
  const regions = KOREA_MAP_PATHS.map((p) => ({
    region: p.region,
    d: p.d,
    count: countByRegion.get(p.region) ?? 0,
  }));

  function handleMove(e: MouseEvent) {
    const box = boxRef.current;
    if (!box) return;
    const b = box.getBoundingClientRect();
    setTipPos({ x: e.clientX - b.left, y: e.clientY - b.top, w: b.width, h: b.height });
  }

  // hover 지역은 SVG 마지막에 그려 돌출·측면이 이웃에 가리지 않게 한다.
  const hoveredRegion = regions.find((r) => r.region === hovered);
  const extrudeLayers = hoveredRegion
    ? Array.from({ length: EXTRUDE_STEPS + 1 }, (_, i) => ({
        key: i,
        x: (EXTRUDE_X * i) / EXTRUDE_STEPS,
        y: (EXTRUDE_Y * i) / EXTRUDE_STEPS,
      }))
    : [];

  return (
    <div className="flex flex-col items-center gap-3">
      <div ref={boxRef} className="relative w-full max-w-md self-center">
        <svg
          viewBox={KOREA_MAP_VIEWBOX}
          className="h-auto w-full overflow-visible"
          role="img"
          aria-label={`시/도별 ${valueLabel} 분포 지도`}
        >
          {regions
            .filter((r) => r.region !== hovered)
            .map((r) => (
              <RegionPath
                key={r.region}
                region={r}
                stats={stats}
                dimmed={hovered !== null}
                hovered={false}
                selected={selectedRegion === r.region}
                unit={unit}
                onRegionClick={onRegionClick}
                onHover={setHovered}
                onMove={handleMove}
              />
            ))}
          <MapInsetGroup
            inset={KOREA_MAP_INSET}
            regions={regions}
            stats={stats}
            hovered={hovered}
            onRegionClick={onRegionClick}
            onHover={setHovered}
            onMove={handleMove}
          />
          {hoveredRegion && (
            <>
              {extrudeLayers.map((l) => (
                <path
                  key={l.key}
                  d={hoveredRegion.d}
                  className="pointer-events-none"
                  style={{ fill: "var(--map-side)", stroke: "var(--map-side)" }}
                  strokeWidth={0.8}
                  strokeLinejoin="round"
                  transform={`translate(${l.x}, ${l.y})`}
                />
              ))}
              <RegionPath
                region={hoveredRegion}
                stats={stats}
                dimmed={false}
                hovered
                selected={selectedRegion === hoveredRegion.region}
                unit={unit}
                onRegionClick={onRegionClick}
                onHover={setHovered}
                onMove={handleMove}
              />
            </>
          )}
        </svg>
        {hoveredRegion && (
          <RegionHoverTip
            region={hoveredRegion}
            stats={stats}
            valueLabel={valueLabel}
            unit={unit}
            x={tipPos.x}
            y={tipPos.y}
            containerWidth={tipPos.w}
            containerHeight={tipPos.h}
          />
        )}
      </div>
      <div className="text-muted-foreground flex items-center gap-2 text-xs tabular-nums">
        <span>{COMPACT.format(stats.minCount)}</span>
        <div
          className="h-3 w-28 rounded"
          style={{
            background: "linear-gradient(to right, var(--map-low), var(--primary))",
          }}
        />
        <span>{COMPACT.format(stats.maxCount)}</span>
      </div>
      <p className="text-muted-foreground text-xs">
        색 농도 = {valueLabel}(√ 보정) · 경계는 단순화된 개략 형상
      </p>
    </div>
  );
}

interface RegionPathProps {
  region: RegionDatum & { d: string };
  stats: RegionStats;
  dimmed: boolean;
  hovered: boolean;
  selected: boolean;
  unit: string;
  onRegionClick?: (region: string) => void;
  onHover: (region: string | null) => void;
  onMove: (e: MouseEvent) => void;
}

function RegionPath({
  region,
  stats,
  dimmed,
  hovered,
  selected,
  unit,
  onRegionClick,
  onHover,
  onMove,
}: RegionPathProps) {
  return (
    <path
      d={region.d}
      data-region={region.region}
      data-count={region.count}
      style={{
        fill: regionFillColor(region.count, stats.maxCount),
        stroke: hovered ? "var(--map-side)" : "var(--card)",
        cursor: onRegionClick ? "pointer" : undefined,
        transition: "filter 150ms, transform 150ms",
        transformBox: "fill-box",
        transformOrigin: "center",
        transform: hovered ? `translate(${EXTRUDE_X}px, ${EXTRUDE_Y}px)` : undefined,
        filter: pathFilter(hovered, dimmed),
      }}
      strokeWidth={pathStrokeWidth(selected, hovered)}
      strokeLinejoin="round"
      strokeLinecap="round"
      role={onRegionClick ? "button" : undefined}
      tabIndex={onRegionClick ? 0 : undefined}
      aria-label={`${region.region} ${region.count.toLocaleString()}${unit}${selected ? " (선택됨)" : ""}`}
      aria-pressed={onRegionClick ? selected : undefined}
      onClick={onRegionClick ? () => onRegionClick(region.region) : undefined}
      onKeyDown={
        onRegionClick
          ? (e) => {
              if (e.key === "Enter" || e.key === " ") {
                e.preventDefault();
                onRegionClick(region.region);
              }
            }
          : undefined
      }
      onMouseEnter={() => onHover(region.region)}
      onMouseLeave={() => onHover(null)}
      onMouseMove={onMove}
      onFocus={() => onHover(region.region)}
      onBlur={() => onHover(null)}
    />
  );
}

function pathFilter(hovered: boolean, dimmed: boolean): string | undefined {
  if (hovered) return "brightness(1.1) saturate(1.15)";
  if (dimmed) return "saturate(0.55) brightness(1.04) opacity(0.75)";
  return undefined;
}

function pathStrokeWidth(selected: boolean, hovered: boolean): number {
  if (selected) return 2;
  return hovered ? 0.8 : 0.6;
}

interface MapInsetGroupProps {
  inset: KoreaMapInset;
  regions: Array<RegionDatum & { d: string }>;
  stats: RegionStats;
  hovered: string | null;
  onRegionClick?: (region: string) => void;
  onHover: (region: string | null) => void;
  onMove: (e: MouseEvent) => void;
}

/** 울릉도·독도 인셋(#58) — hover/클릭은 parent(경상북도)로 연동한다. */
function MapInsetGroup({
  inset,
  regions,
  stats,
  hovered,
  onRegionClick,
  onHover,
  onMove,
}: MapInsetGroupProps) {
  const parent = regions.find((r) => r.region === inset.parent);
  const fill = parent
    ? regionFillColor(parent.count, stats.maxCount)
    : "var(--map-low)";
  const dimmed = hovered !== null && hovered !== inset.parent;

  return (
    <g>
      <rect
        x={inset.box.x}
        y={inset.box.y}
        width={inset.box.w}
        height={inset.box.h}
        rx={6}
        style={{
          fill: "color-mix(in oklch, var(--card) 55%, transparent)",
          stroke: "var(--muted-foreground)",
          strokeWidth: 0.8,
          strokeDasharray: "4 3",
        }}
      />
      <text
        x={inset.box.x + inset.box.w - 8}
        y={inset.box.y + 14}
        textAnchor="end"
        className="text-[10px] tracking-widest"
        style={{ fill: "var(--muted-foreground)" }}
      >
        {inset.seaLabel}
      </text>
      {inset.islands.map((island) => (
        <g key={island.name}>
          <path
            d={island.d}
            style={{
              fill,
              stroke: "var(--card)",
              strokeWidth: 0.6,
              strokeLinejoin: "round",
              cursor: onRegionClick ? "pointer" : undefined,
              transition: "filter 150ms",
              filter: dimmed
                ? "saturate(0.55) brightness(1.04) opacity(0.75)"
                : undefined,
            }}
            aria-label={`${island.name} (${inset.parent})`}
            onClick={
              onRegionClick ? () => onRegionClick(inset.parent) : undefined
            }
            onMouseEnter={() => onHover(inset.parent)}
            onMouseLeave={() => onHover(null)}
            onMouseMove={onMove}
          />
          <text
            x={island.labelX}
            y={island.labelY}
            textAnchor="middle"
            className="pointer-events-none text-[10.5px]"
            style={{ fill: "var(--muted-foreground)" }}
          >
            {island.name}
          </text>
        </g>
      ))}
    </g>
  );
}

"use client";

import { useRef, useState, type ComponentProps, type MouseEvent } from "react";

import {
  RegionHoverTip,
  regionFillColor,
  regionShare,
  buildRegionStats,
  type RegionDatum,
} from "./shared";

// 실제 지리 위상을 따른 개략 배치 — [col, row].
const GRID: Record<string, [number, number]> = {
  서울특별시: [1, 0],
  강원특별자치도: [3, 0],
  인천광역시: [0, 1],
  경기도: [1, 1],
  충청북도: [2, 1],
  경상북도: [3, 1],
  충청남도: [0, 2],
  세종특별자치시: [1, 2],
  대전광역시: [2, 2],
  대구광역시: [3, 2],
  전북특별자치도: [0, 3],
  광주광역시: [1, 3],
  경상남도: [2, 3],
  울산광역시: [3, 3],
  전라남도: [0, 4],
  부산광역시: [2, 4],
  제주특별자치도: [0, 5],
};

const SHORT_NAME: Record<string, string> = {
  서울특별시: "서울",
  강원특별자치도: "강원",
  인천광역시: "인천",
  경기도: "경기",
  충청북도: "충북",
  경상북도: "경북",
  충청남도: "충남",
  세종특별자치시: "세종",
  대전광역시: "대전",
  대구광역시: "대구",
  전북특별자치도: "전북",
  광주광역시: "광주",
  경상남도: "경남",
  울산광역시: "울산",
  전라남도: "전남",
  부산광역시: "부산",
  제주특별자치도: "제주",
};

const CELL = 112;
const PAD = 10;
const MAX_SIDE = 100;
const MIN_SIDE = 34;
// 이 변 길이 이상이면 큰 라벨(15/12px), 미만이면 축소 라벨(12/10px)로 내부 표기.
const LABEL_LARGE_SIDE = 52;
const VIEW_W = PAD * 2 + CELL * 4;
const VIEW_H = PAD * 2 + CELL * 6;
const EXTRUDE_X = -4;
const EXTRUDE_Y = -8;

export interface RegionCartogramProps {
  data: RegionDatum[];
  valueLabel: string;
  unit: string;
  selectedRegion: string;
  onRegionClick?: (region: string) => void;
}

/**
 * Demers 타일 카토그램 — 타일 면적이 값에 비례해, 지리 지도의 "면적 큰 지역
 * 과대평가" 왜곡을 보완하는 보조 뷰. 위치는 GRID 개략 배치.
 */
export function RegionCartogram({
  data,
  valueLabel,
  unit,
  selectedRegion,
  onRegionClick,
}: RegionCartogramProps) {
  const boxRef = useRef<HTMLDivElement | null>(null);
  const [hovered, setHovered] = useState<string | null>(null);
  const [tipPos, setTipPos] = useState({ x: 0, y: 0, w: 0, h: 0 });
  const stats = buildRegionStats(data);

  function handleMove(e: MouseEvent) {
    const box = boxRef.current;
    if (!box) return;
    const b = box.getBoundingClientRect();
    setTipPos({ x: e.clientX - b.left, y: e.clientY - b.top, w: b.width, h: b.height });
  }

  const placed = data.filter((r) => GRID[r.region]);
  // hover 타일은 SVG 마지막에 그려 돌출·측면이 이웃에 가리지 않게 한다.
  const ordered = hovered
    ? [...placed.filter((r) => r.region !== hovered), ...placed.filter((r) => r.region === hovered)]
    : placed;
  const hoveredRegion = placed.find((r) => r.region === hovered);

  return (
    <div className="flex flex-col items-center gap-3">
      <div ref={boxRef} className="relative w-full max-w-md self-center">
        <svg
          viewBox={`0 0 ${VIEW_W} ${VIEW_H}`}
          className="h-auto w-full overflow-visible"
          role="img"
          aria-label={`시/도별 ${valueLabel} 분포 카토그램`}
        >
          {ordered.map((r) => (
            <CartogramTile
              key={r.region}
              region={r}
              maxCount={stats.maxCount}
              total={stats.total}
              dimmed={hovered !== null && hovered !== r.region}
              hovered={hovered === r.region}
              selected={selectedRegion === r.region}
              unit={unit}
              onRegionClick={onRegionClick}
              onHover={setHovered}
              onMove={handleMove}
            />
          ))}
        </svg>
        {hoveredRegion && (
          <RegionHoverTip
            region={hoveredRegion}
            stats={stats}
            valueLabel={valueLabel}
            unit={unit}
            x={tipPos.x}
            y={tipPos.y}
            containerWidth={tipPos.w}
            containerHeight={tipPos.h}
          />
        )}
      </div>
      <p className="text-muted-foreground text-xs">
        타일 면적·색 = {valueLabel} 비례(√ 스케일) · 위치는 개략 배치
      </p>
    </div>
  );
}

interface CartogramTileProps {
  region: RegionDatum;
  maxCount: number;
  total: number;
  dimmed: boolean;
  hovered: boolean;
  selected: boolean;
  unit: string;
  onRegionClick?: (region: string) => void;
  onHover: (region: string | null) => void;
  onMove: (e: MouseEvent) => void;
}

interface TileGeometry {
  side: number;
  cx: number;
  cy: number;
  largeLabel: boolean;
  labelFill: string;
}

/** GRID 좌표와 값 비율에서 타일 한 장의 배치·크기·라벨 표기를 계산한다. */
function tileGeometry(count: number, maxCount: number, col: number, row: number): TileGeometry {
  const ratio = maxCount > 0 ? count / maxCount : 0;
  const side = MIN_SIDE + (MAX_SIDE - MIN_SIDE) * Math.sqrt(ratio);
  // 진한 타일 내부 라벨은 배경색 글자로 대비 확보(√ 보간 55% 이상 = 진한 편).
  const darkFill = Math.pow(ratio, 0.45) > 0.5;
  return {
    side,
    cx: PAD + col * CELL + CELL / 2,
    cy: PAD + row * CELL + CELL / 2,
    largeLabel: side >= LABEL_LARGE_SIDE,
    labelFill: darkFill ? "var(--background)" : "var(--foreground)",
  };
}

type TileInteraction = Pick<
  ComponentProps<"g">,
  "role" | "tabIndex" | "aria-pressed" | "onClick" | "onKeyDown"
>;

/** 클릭 핸들러가 있을 때만 버튼 시맨틱(role/tabIndex/Enter·Space)을 부여한다. */
function tileInteraction(
  region: string,
  selected: boolean,
  onRegionClick?: (region: string) => void,
): TileInteraction {
  if (!onRegionClick) return {};
  return {
    role: "button",
    tabIndex: 0,
    "aria-pressed": selected,
    onClick: () => onRegionClick(region),
    onKeyDown: (e) => {
      if (e.key !== "Enter" && e.key !== " ") return;
      e.preventDefault();
      onRegionClick(region);
    },
  };
}

function tileAriaLabel(region: RegionDatum, unit: string, selected: boolean): string {
  return `${region.region} ${region.count.toLocaleString()}${unit}${selected ? " (선택됨)" : ""}`;
}

function TileLabels({
  region,
  total,
  cx,
  cy,
  largeLabel,
  labelFill,
}: Readonly<{
  region: RegionDatum;
  total: number;
  cx: number;
  cy: number;
  largeLabel: boolean;
  labelFill: string;
}>) {
  return (
    <>
      <text
        x={cx}
        y={largeLabel ? cy - 3 : cy - 2}
        textAnchor="middle"
        className={`pointer-events-none font-semibold ${largeLabel ? "text-[15px]" : "text-[12px]"}`}
        style={{ fill: labelFill }}
      >
        {SHORT_NAME[region.region] ?? region.region}
      </text>
      <text
        x={cx}
        y={largeLabel ? cy + 14 : cy + 11}
        textAnchor="middle"
        className={`pointer-events-none opacity-80 ${largeLabel ? "text-[12px]" : "text-[10px]"}`}
        style={{ fill: labelFill }}
      >
        {regionShare(region.count, total)}%
      </text>
    </>
  );
}

function CartogramTile({
  region,
  maxCount,
  total,
  dimmed,
  hovered,
  selected,
  unit,
  onRegionClick,
  onHover,
  onMove,
}: CartogramTileProps) {
  const [col, row] = GRID[region.region];
  const { side, cx, cy, largeLabel, labelFill } = tileGeometry(region.count, maxCount, col, row);

  return (
    <g
      data-region={region.region}
      data-count={region.count}
      style={{
        cursor: onRegionClick ? "pointer" : undefined,
        filter: hoverFilter(hovered, dimmed),
        transition: "filter 150ms",
      }}
      aria-label={tileAriaLabel(region, unit, selected)}
      {...tileInteraction(region.region, selected, onRegionClick)}
      onMouseEnter={() => onHover(region.region)}
      onMouseLeave={() => onHover(null)}
      onMouseMove={onMove}
      onFocus={() => onHover(region.region)}
      onBlur={() => onHover(null)}
    >
      {hovered && (
        // 돌출 측면 — 원위치 바닥 타일이 두께로 보인다.
        <rect
          x={cx - side / 2}
          y={cy - side / 2}
          width={side}
          height={side}
          rx={8}
          className="pointer-events-none"
          style={{ fill: "var(--map-side)" }}
        />
      )}
      <g
        transform={hovered ? `translate(${EXTRUDE_X}, ${EXTRUDE_Y})` : undefined}
        style={{ transition: "transform 150ms" }}
      >
        <rect
          x={cx - side / 2}
          y={cy - side / 2}
          width={side}
          height={side}
          rx={8}
          stroke={selected ? "var(--foreground)" : "var(--card)"}
          strokeWidth={selected ? 2 : 1}
          style={{ fill: regionFillColor(region.count, maxCount) }}
        />
        <TileLabels
          region={region}
          total={total}
          cx={cx}
          cy={cy}
          largeLabel={largeLabel}
          labelFill={labelFill}
        />
      </g>
    </g>
  );
}

function hoverFilter(hovered: boolean, dimmed: boolean): string | undefined {
  if (hovered) return "brightness(1.1) saturate(1.15)";
  if (dimmed) return "saturate(0.55) opacity(0.7)";
  return undefined;
}

"use client";

/** 지도·카토그램이 공유하는 시/도 1건의 값. */
export interface RegionDatum {
  /** 시/도 공식 명칭 — korea-map-paths.ts 의 region 과 일치해야 한다. */
  region: string;
  count: number;
}

export interface RegionStats {
  total: number;
  maxCount: number;
  minCount: number;
  /** count 내림차순 정렬본 — 툴팁 상위 랭킹 표시용. */
  ranked: RegionDatum[];
  rankOf: Map<string, number>;
}

export function buildRegionStats(regions: RegionDatum[]): RegionStats {
  const ranked = [...regions].sort((a, b) => b.count - a.count);
  return {
    total: regions.reduce((s, r) => s + r.count, 0),
    maxCount: ranked[0]?.count ?? 0,
    minCount: ranked[ranked.length - 1]?.count ?? 0,
    ranked,
    rankOf: new Map(ranked.map((r, i) => [r.region, i + 1])),
  };
}

export function regionShare(count: number, total: number): string {
  return total > 0 ? ((count / total) * 100).toFixed(1) : "0.0";
}

/**
 * 색 스케일 — 투명도 대신 oklch 단색 보간이라 지도가 이어진 색 면으로 보인다.
 * pow 0.45 는 특정 지역 쏠림(수도권 등)으로 중간·하위 색이 뭉개지는 것을 보정.
 * --map-low 는 RegionMap 루트가 primary·background 조합으로 파생 정의한다.
 */
export function regionFillColor(count: number, maxCount: number): string {
  const ratio = maxCount > 0 ? count / maxCount : 0;
  const t = Math.round((0.1 + Math.pow(ratio, 0.45) * 0.9) * 100);
  return `color-mix(in oklch, var(--primary) ${t}%, var(--map-low))`;
}

const TIP_OFFSET = 14;
const TOP_RANKS = 5;

interface RegionHoverTipProps {
  region: RegionDatum;
  stats: RegionStats;
  /** 툴팁 항목명 (예: "사업자", "가맹점"). */
  valueLabel: string;
  /** 값 단위 접미사 (예: "건", "곳"). */
  unit: string;
  /** 컨테이너 기준 커서 좌표 — 컨테이너를 넘치면 반대편으로 플립한다. */
  x: number;
  y: number;
  /** 컨테이너 크기 — 이벤트 핸들러에서 측정해 넘긴다(렌더 중 ref 접근 금지). */
  containerWidth: number;
  containerHeight: number;
}

/** 리치 툴팁 — 값·비중·순위 + 상위 5개 지역 랭킹 바. */
export function RegionHoverTip({
  region,
  stats,
  valueLabel,
  unit,
  x,
  y,
  containerWidth,
  containerHeight,
}: RegionHoverTipProps) {
  const rows = stats.ranked.slice(0, TOP_RANKS);
  if (!rows.some((r) => r.region === region.region)) {
    rows.push(region);
  }

  // 툴팁 크기 근사치로 플립 판정 — 실측 폭 재계산은 과한 리렌더.
  const approxW = 200;
  const approxH = 190;
  let left = x + TIP_OFFSET;
  let top = y + TIP_OFFSET;
  if (containerWidth > 0 && left + approxW > containerWidth) left = x - approxW - TIP_OFFSET;
  if (containerHeight > 0 && top + approxH > containerHeight) {
    top = Math.max(0, y - approxH - TIP_OFFSET);
  }

  return (
    <div
      role="tooltip"
      className="bg-popover text-popover-foreground pointer-events-none absolute z-10 min-w-44 rounded-md border p-3 text-xs shadow-md"
      style={{ left, top }}
    >
      <div className="mb-1 text-[13px] font-semibold">{region.region}</div>
      <TipRow label={valueLabel} value={`${region.count.toLocaleString()}${unit}`} />
      <TipRow label="비중" value={`${regionShare(region.count, stats.total)}%`} />
      <TipRow
        label="순위"
        value={`${stats.rankOf.get(region.region)}위 / ${stats.ranked.length}`}
      />
      <div className="bg-muted mt-2 h-1 overflow-hidden rounded-sm">
        <div
          className="bg-primary h-full"
          style={{ width: `${regionShare(region.count, stats.total)}%` }}
        />
      </div>
      <div className="mt-2 flex flex-col gap-1">
        {rows.map((r) => (
          <RankRow key={r.region} row={r} stats={stats} current={r.region === region.region} />
        ))}
      </div>
    </div>
  );
}

function TipRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="text-muted-foreground flex justify-between gap-4 tabular-nums">
      <span>{label}</span>
      <b className="text-popover-foreground font-semibold">{value}</b>
    </div>
  );
}

function RankRow({
  row,
  stats,
  current,
}: {
  row: RegionDatum;
  stats: RegionStats;
  current: boolean;
}) {
  return (
    <div
      className={`grid grid-cols-[4.5em_1fr_3.5em] items-center gap-1.5 text-[11px] tabular-nums ${
        current ? "text-popover-foreground font-semibold" : "text-muted-foreground"
      }`}
    >
      <span>{row.region.slice(0, 4)}</span>
      <span className="bg-muted h-1 overflow-hidden rounded-sm">
        <span
          className={`bg-primary block h-full ${current ? "" : "opacity-45"}`}
          style={{
            width: `${stats.maxCount > 0 ? (row.count / stats.maxCount) * 100 : 0}%`,
          }}
        />
      </span>
      <span className="text-right">{regionShare(row.count, stats.total)}%</span>
    </div>
  );
}

